import { validEnvelope, validKeyMaterial, validateUsername, validAttachmentId, validAttachmentEnvelope, validInviteCode, MAX_ATTACHMENT_CIPHERTEXT } from '../../../shared/contract.mjs';
import { classifySessionClient, normalizeSessionIp } from '../../../shared/session-metadata.mjs';
// @ts-expect-error The repository's wildcard .mjs declaration has not added this shared module yet.
import { parsePasskeyUnlockKek, sealVaultKeyForServer, openVaultKeyFromServer, passkeyRegistrationOptions, passkeyAuthenticationOptions, verifyPasskeyRegistration, verifyPasskeyAuthentication, encodeBase64url, decodeBase64url, validatePasskeyCredentialId } from '../../../shared/passkey-assisted-unlock.mjs';

interface Env { DB:D1Database; ASSETS:Fetcher; ATTACHMENTS:R2Bucket; INVITE_CODE?:string; PASSKEY_UNLOCK_KEK?:string; PASSKEY_RP_ID?:string; PASSKEY_ORIGIN?:string }
type User={id:string;username:string;password_hash:string;password_salt:string;password_iterations?:number;kdf:string;wrapped_key:string};
type Session=User&{user_id:string;id_hash:string;csrf_hash:string;expires_at:number;public_id:string;created_at:number;last_seen_at:number;ip_address:string;device_type:string;browser:string;auth_method:'password'|'passkey'|'unknown'};
type Envelope={id:string;type:'account'|'website'|'note';version:number;iv:string;ciphertext:string};
type StoredEnvelope=Envelope&{createdAt:number;revision:number};
type PasskeyChallenge={id_hash:string;user_id:string|null;purpose:'registration'|'authentication';challenge:string;expires_at:number;created_at:number};
type PasskeyCredential={id:string;user_id:string;public_key:string;counter:number;transports:string;device_type:string;backed_up:number;server_wrapped_key:string;created_at:number;updated_at:number;username?:string};
const COOKIE='pv_session', SESSION_SECONDS=28800, ACTIVITY_WRITE_MS=5*60*1000, PASSKEY_CHALLENGE_MS=5*60*1000, MAX_BODY=2_000_000, LOGIN_WINDOW=60_000, LOGIN_LIMIT=10, PASSWORD_ITERATIONS_LEGACY=100_000, PASSWORD_ITERATIONS_CURRENT=100_000, REAUTH_LIMIT=10, MAX_BACKUP_ENTRIES=900, MAX_BACKUP_ATTACHMENTS_COUNT=8, MAX_BACKUP_ATTACHMENTS=8*1024*1024, MAX_BACKUP_JSON=12*1024*1024, MAX_WORKER_UPLOAD=20*1024*1024+16;
const CAPABILITIES={backend:'d1',maxAttachmentBytes:20*1024*1024,maxBackupAttachmentBytes:8*1024*1024};
const enc=new TextEncoder();
export const R2_QUOTAS={storageBytes:8*1024**3,classA:800_000,classB:8_000_000} as const;
export const utcMonth=(date=new Date())=>date.toISOString().slice(0,7);
class QuotaExceeded extends Error{quota:'storage'|'class_a'|'class_b';constructor(quota:'storage'|'class_a'|'class_b'){super('quota_exceeded');this.quota=quota}}
async function reserveOperation(env:Env,kind:'class_a'|'class_b',count=1){const month=utcMonth();await env.DB.prepare('INSERT INTO r2_monthly_usage(month,class_a,class_b) VALUES(?,0,0) ON CONFLICT(month) DO NOTHING').bind(month).run();const column=kind==='class_a'?'class_a':'class_b',limit=kind==='class_a'?R2_QUOTAS.classA:R2_QUOTAS.classB;const result=await env.DB.prepare(`UPDATE r2_monthly_usage SET ${column}=${column}+? WHERE month=? AND ${column}+?<=?`).bind(count,month,count,limit).run();if(!result.meta.changes)throw new QuotaExceeded(kind)}
async function ensureStorageCounter(env:Env){const total=Number((await env.DB.prepare('SELECT COALESCE(SUM(ciphertext_size),0) AS total FROM attachments').first<{total:number}>())?.total||0);await env.DB.prepare('INSERT INTO r2_storage_usage(id,reserved_bytes) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET reserved_bytes=MAX(reserved_bytes,excluded.reserved_bytes)').bind(total).run()}
async function reserveStorage(env:Env,delta:number){await ensureStorageCounter(env);const result=await env.DB.prepare('UPDATE r2_storage_usage SET reserved_bytes=reserved_bytes+? WHERE id=1 AND reserved_bytes+?>=0 AND reserved_bytes+?<=?').bind(delta,delta,delta,R2_QUOTAS.storageBytes).run();if(!result.meta.changes)throw new QuotaExceeded('storage')}
async function cleanupPendingR2(env:Env){try{const row=await env.DB.prepare('SELECT object_key,ciphertext_size FROM pending_r2_deletions ORDER BY created_at LIMIT ?').bind(1).first<any>();if(!row)return;if(await env.DB.prepare('SELECT 1 FROM attachments WHERE object_key=?').bind(row.object_key).first()){await env.DB.prepare('DELETE FROM pending_r2_deletions WHERE object_key=?').bind(row.object_key).run();return}await env.ATTACHMENTS.delete(row.object_key);await env.DB.batch([env.DB.prepare('DELETE FROM pending_r2_deletions WHERE object_key=?').bind(row.object_key),env.DB.prepare('UPDATE r2_storage_usage SET reserved_bytes=reserved_bytes-? WHERE id=1 AND changes()=1 AND reserved_bytes>=?').bind(Number(row.ciphertext_size),Number(row.ciphertext_size))])}catch{}}
async function acquireBackupLock(env:Env,userId:string){const token=random(24),now=Date.now(),result=await env.DB.prepare('INSERT INTO backup_import_locks(user_id,token,expires_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET token=excluded.token,expires_at=excluded.expires_at WHERE backup_import_locks.expires_at<=?').bind(userId,token,now+10*60*1000,now).run();return result.meta.changes===1?token:null}
async function renewBackupLock(env:Env,userId:string,token:string){const result=await env.DB.prepare('UPDATE backup_import_locks SET expires_at=? WHERE user_id=? AND token=?').bind(Date.now()+10*60*1000,userId,token).run();if(result.meta.changes!==1)throw new Error('stale_backup_lock')}
async function releaseBackupLock(env:Env,userId:string,token:string){try{await env.DB.prepare('DELETE FROM backup_import_locks WHERE user_id=? AND token=?').bind(userId,token).run()}catch{}}
async function reconcileR2(env:Env){const rows=await env.DB.prepare('SELECT object_key FROM attachments UNION SELECT object_key FROM pending_r2_deletions UNION SELECT object_key FROM r2_inflight_uploads').all<{object_key:string}>(),known=new Set(rows.results.map(x=>x.object_key)),cutoff=Date.now()-15*60*1000;let cursor: string|undefined;do{const page=await env.ATTACHMENTS.list({cursor,limit:1000});const now=Date.now();for(const object of page.objects)if(object.uploaded.getTime()<=cutoff&&!known.has(object.key))await env.DB.prepare('INSERT INTO pending_r2_deletions(object_key,ciphertext_size,created_at) VALUES(?,?,?) ON CONFLICT(object_key) DO NOTHING').bind(object.key,object.size,now).run();cursor=page.truncated?page.cursor:undefined}while(cursor)}
async function scheduledMaintenance(env:Env){try{const now=Date.now(),stale=now-24*60*60*1000;await env.DB.prepare('INSERT INTO pending_r2_deletions(object_key,ciphertext_size,created_at) SELECT object_key,ciphertext_size,? FROM r2_inflight_uploads WHERE created_at<=? ON CONFLICT(object_key) DO NOTHING').bind(now,stale).run();await env.DB.prepare('DELETE FROM r2_inflight_uploads WHERE created_at<=?').bind(stale).run();await reconcileR2(env);for(let i=0;i<20;i++)await cleanupPendingR2(env);await env.DB.batch([env.DB.prepare('DELETE FROM sessions WHERE expires_at<=?').bind(now),env.DB.prepare('DELETE FROM backup_import_locks WHERE expires_at<=?').bind(stale),env.DB.prepare('DELETE FROM passkey_challenges WHERE expires_at<=?').bind(now),env.DB.prepare('DELETE FROM login_attempts WHERE attempted_at<?').bind(now-LOGIN_WINDOW),env.DB.prepare('DELETE FROM invite_attempts WHERE attempted_at<?').bind(now-LOGIN_WINDOW)])}catch(e){console.error(JSON.stringify({event:'scheduled_maintenance_error',message:e instanceof Error?e.message:'unknown'}))}}
const SECURITY_HEADERS={
 'content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data: blob:; media-src 'self' blob:; frame-src 'self' blob:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
 'permissions-policy':'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
 'referrer-policy':'no-referrer',
 'strict-transport-security':'max-age=63072000; includeSubDomains; preload',
 'x-content-type-options':'nosniff',
 'x-frame-options':'DENY'
} as const;
const json=(value:unknown,status=200,headers:HeadersInit={})=>Response.json(value,{status,headers:{...SECURITY_HEADERS,'cache-control':'no-store',...headers}});
async function asset(req:Request,env:Env){const response=await env.ASSETS.fetch(req),headers=new Headers(response.headers);for(const [key,value] of Object.entries(SECURITY_HEADERS))headers.set(key,value);return new Response(response.body,{status:response.status,statusText:response.statusText,headers})}
const error=(status:number,code:string)=>json({error:code},status);
const b64=(bytes:ArrayBuffer|Uint8Array)=>{const a=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);let s='';for(const x of a)s+=String.fromCharCode(x);return btoa(s).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')};
const random=(n=32)=>{const x=new Uint8Array(n);crypto.getRandomValues(x);return b64(x)};
const digest=async(value:string)=>b64(await crypto.subtle.digest('SHA-256',enc.encode(value)));
const digestBytes=async(value:ArrayBuffer)=>b64(await crypto.subtle.digest('SHA-256',value));
const bytesToB64=(value:ArrayBuffer)=>{let out='';for(const x of new Uint8Array(value))out+=String.fromCharCode(x);return btoa(out)};
const b64ToBytes=(value:string)=>{try{return Uint8Array.from(atob(value),c=>c.charCodeAt(0))}catch{return null}};
const equal=(a:string,b:string)=>{if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0};
const passwordHash=async(password:string,salt:string,iterations=PASSWORD_ITERATIONS_CURRENT)=>b64(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:enc.encode(salt),iterations},await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']),256));
const passwordMatches=async(password:unknown,user:Pick<User,'password_hash'|'password_salt'|'password_iterations'>)=>typeof password==='string'&&equal(await passwordHash(password,user.password_salt,Number(user.password_iterations)||PASSWORD_ITERATIONS_LEGACY),user.password_hash);
const inviteMatches=async(a:string,b:string)=>equal(await digest(a),await digest(b));
async function body(req:Request){const length=Number(req.headers.get('content-length')||0);if(length>MAX_BODY)throw new RangeError();const text=await req.text();if(text.length>MAX_BODY)throw new RangeError();return JSON.parse(text||'{}') as Record<string,unknown>}
async function limitedJson(req:Request,limit:number){const reader=req.body?.getReader();if(!reader)return {};const chunks:Uint8Array[]=[];let size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>limit){await reader.cancel();throw new RangeError()}chunks.push(value)}const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.byteLength}return JSON.parse(new TextDecoder().decode(bytes)||'{}') as any}
const validPassword=(x:unknown)=>typeof x==='string'&&x.length>=12&&x.length<=1024;
const validKey=(x:Record<string,unknown>)=>validKeyMaterial(x);
const material=(u:{kdf:string;wrapped_key:string})=>({kdf:JSON.parse(u.kdf),wrappedKey:JSON.parse(u.wrapped_key)});
function passkeyContext(env:Env){const kek=parsePasskeyUnlockKek(env.PASSKEY_UNLOCK_KEK),rpID=env.PASSKEY_RP_ID?.trim(),configuredOrigin=env.PASSKEY_ORIGIN?.trim();if(!kek||!rpID||!configuredOrigin)return null;try{const origin=new URL(configuredOrigin);if(origin.origin!==configuredOrigin||origin.protocol!=='https:'||origin.hostname!==rpID)return null;return{kek,rpID,origin:origin.origin}}catch{return null}}
const emptyObject=(value:unknown)=>value!==null&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length===0;
async function savePasskeyChallenge(env:Env,userId:string|null,purpose:'registration'|'authentication',challenge:string){const token=random(),now=Date.now();await env.DB.prepare('DELETE FROM passkey_challenges WHERE expires_at<=?').bind(now).run();await env.DB.prepare('INSERT INTO passkey_challenges(id_hash,user_id,purpose,challenge,expires_at,created_at) VALUES(?,?,?,?,?,?)').bind(await digest(token),userId,purpose,challenge,now+PASSKEY_CHALLENGE_MS,now).run();return token}
async function consumePasskeyChallenge(env:Env,token:unknown,purpose:'registration'|'authentication',userId?:string){const bytes=decodeBase64url(token);if(bytes?.length!==32)return null;const idHash=await digest(token as string),row=userId===undefined?await env.DB.prepare('DELETE FROM passkey_challenges WHERE id_hash=? AND purpose=? RETURNING id_hash,user_id,purpose,challenge,expires_at,created_at').bind(idHash,purpose).first<PasskeyChallenge>():await env.DB.prepare('DELETE FROM passkey_challenges WHERE id_hash=? AND purpose=? AND user_id=? RETURNING id_hash,user_id,purpose,challenge,expires_at,created_at').bind(idHash,purpose,userId).first<PasskeyChallenge>();return row&&row.expires_at>Date.now()?row:null}
function passkeyRequest(value:Record<string,unknown>,keys:string[]){return Object.keys(value).sort().join(',')===keys.slice().sort().join(',')}
async function passkeySessionValues(req:Request,userId:string){const token=random(),csrf=random(24),sessionId=random(18),now=Date.now(),client=classifySessionClient(req.headers.get('user-agent')||''),ip=normalizeSessionIp(req.headers.get('CF-Connecting-IP')||'');return{token,csrf,sessionId,now,values:[await digest(token),userId,await digest(csrf),now+SESSION_SECONDS*1000,sessionId,now,now,ip,client.device,client.browser,'passkey'] as const}}
function cookie(req:Request){for(const part of (req.headers.get('cookie')||'').split(';')){const [k,...v]=part.trim().split('=');if(k===COOKIE)return v.join('=')}return null}
async function session(req:Request,env:Env){const token=cookie(req);if(!token)return null;return env.DB.prepare('SELECT s.id_hash,s.user_id,s.csrf_hash,s.expires_at,s.public_id,s.created_at,s.last_seen_at,s.ip_address,s.device_type,s.browser,s.auth_method,u.id,u.username,u.password_hash,u.password_salt,u.password_iterations,u.kdf,u.wrapped_key FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id_hash = ? AND s.expires_at > ?').bind(await digest(token),Date.now()).first<Session>()}
async function safe(req:Request,s:Session){const origin=req.headers.get('origin'),expected=new URL(req.url).origin,token=req.headers.get('x-csrf-token');return origin===expected&&!!token&&equal(await digest(token),s.csrf_hash)}
async function takeRateSlot(env:Env,key:string,table:'login_attempts'|'invite_attempts'='login_attempts',limit=LOGIN_LIMIT){const cutoff=Date.now()-LOGIN_WINDOW,randomPart=new Uint32Array(1);crypto.getRandomValues(randomPart);const slot=Date.now()+randomPart[0]/0x1_0000_0000,results=await env.DB.batch([env.DB.prepare(`DELETE FROM ${table} WHERE attempted_at < ?`).bind(cutoff),env.DB.prepare(`INSERT INTO ${table}(key,attempted_at) SELECT ?,? WHERE (SELECT COUNT(*) FROM ${table} WHERE key=? AND attempted_at>?) < ?`).bind(key,slot,key,cutoff,limit)]);return results[1].meta.changes===1?slot:null}
async function keepRateFailure(env:Env,key:string,slot:number,table:'login_attempts'|'invite_attempts'='login_attempts'){await env.DB.prepare(`UPDATE ${table} SET attempted_at=? WHERE key=? AND attempted_at=?`).bind(Date.now(),key,slot).run()}
async function releaseRateSlot(env:Env,key:string,slot:number,table:'login_attempts'|'invite_attempts'='login_attempts'){await env.DB.prepare(`DELETE FROM ${table} WHERE key=? AND attempted_at=?`).bind(key,slot).run()}
const reauthKey=(req:Request,s:Session)=>`reauth:${s.user_id}:${s.public_id}:${req.headers.get('CF-Connecting-IP')||'unknown'}`;
async function verifyCurrentPassword(req:Request,env:Env,s:Session,password:unknown){const key=reauthKey(req,s),slot=await takeRateSlot(env,key,'login_attempts',REAUTH_LIMIT);if(slot===null)return{ok:false as const,limited:true as const};if(!validPassword(password)||!await passwordMatches(password,s)){await keepRateFailure(env,key,slot);return{ok:false as const,limited:false as const}}await releaseRateSlot(env,key,slot);return{ok:true as const,limited:false as const}}
function insertEntriesFromBackup(env:Env,userId:string,lock:string,items:Envelope[],now:number){const payload=JSON.stringify(items);return env.DB.prepare(`INSERT INTO entries(user_id,id,type,version,iv,ciphertext,created_at,updated_at,revision) SELECT ?,json_extract(value,'$.id'),json_extract(value,'$.type'),json_extract(value,'$.version'),json_extract(value,'$.iv'),json_extract(value,'$.ciphertext'),?,?,COALESCE((SELECT last_revision+1 FROM revision_tombstones WHERE user_id=? AND resource_type='entry' AND id=json_extract(value,'$.id')),1) FROM json_each(?) WHERE EXISTS(SELECT 1 FROM backup_import_locks WHERE user_id=? AND token=?)`).bind(userId,now,now,userId,payload,userId,lock)}
const envelope=(x:Record<string,unknown>,id?:string):Envelope|null=>{const y={...x,...(id?{id}:{})};return Object.keys(y).every(k=>['id','type','version','iv','ciphertext'].includes(k))&&validEnvelope(y)?y as Envelope:null};

