   if(await env.DB.prepare('SELECT id FROM users WHERE username = ?').bind(name.value).first()){await releaseRateSlot(env,key,slot,'invite_attempts');return error(409,'username_taken')}
   const id=crypto.randomUUID(),salt=random(16),hash=await passwordHash(x.password as string,salt);try{await env.DB.prepare('INSERT INTO users(id,username,password_hash,password_salt,password_iterations,kdf,wrapped_key,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(id,name.value,hash,salt,PASSWORD_ITERATIONS_CURRENT,JSON.stringify(x.kdf),JSON.stringify(x.wrappedKey),Date.now()).run()}catch(e){await releaseRateSlot(env,key,slot,'invite_attempts');if(String(e).includes('UNIQUE'))return error(409,'username_taken');throw e}await releaseRateSlot(env,key,slot,'invite_attempts');return json({ok:true},201);
